package dev.trentdb.storage;
import dev.trentdb.ast.*; import dev.trentdb.catalog.*; import dev.trentdb.transaction.*; import dev.trentdb.types.*; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class RowIdTombstoneTest {
 @Test void targetedRowsUseStableIdsAndRollbackRestoresNullRows(){var catalog=new Catalog();var storage=new StorageManager();var manager=new TransactionManager();var create=manager.startTransaction();var table=catalog.createTable(create,new QualifiedName(List.of("rows")),List.of(new ColumnDefinition("id",TypeName.BIGINT),new ColumnDefinition("note",TypeName.TEXT)));storage.stageCreate(create,table);manager.commit(create);var write=manager.startTransaction();assertEquals(1,storage.stageAppend(write,table,java.util.Arrays.asList(1L,null)));assertEquals(2,storage.stageAppend(write,table,List.of(2L,"two")));manager.commit(write);var old=manager.startTransaction();var delete=manager.startTransaction();storage.stageDelete(delete,table,List.of(1L));assertEquals(1,storage.getTable(table).scanChunks(delete).getFirst().cardinality());assertEquals(2,storage.getTable(table).scanChunks(old).getFirst().cardinality());manager.rollback(delete);assertEquals(2,storage.getTable(table).scanChunks(manager.startTransaction()).getFirst().cardinality());}
 @Test void recoveryRowIdMustBeNext(){var catalog=new Catalog();var storage=new StorageManager();var manager=new TransactionManager();var tx=manager.startTransaction();var table=catalog.createTable(tx,new QualifiedName(List.of("rows")),List.of(new ColumnDefinition("id",TypeName.BIGINT)));storage.stageCreate(tx,table);manager.commit(tx);var append=manager.startTransaction();assertThrows(StorageException.class,()->storage.stageAppend(append,table,List.of(1L),2));manager.rollback(append);}
}
